import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Triangle t = new Triangle();
        Square s = new Square();
        t.title = "Triangle";
        s.title = "Square";
        t.base = sc.nextDouble();
        t.height = sc.nextDouble();
        s.side = sc.nextDouble();
        System.out.printf(t.title + " area: %.2f%n", t.area());
        System.out.printf(s.title + " area: %.2f%n", s.area());
    }
}

class Shape {
    String title;
}

class Triangle extends Shape {
    double base;
    double height;

    double area() {
        return 0.5 * base * height;
    }
}

class Square extends Shape {
    double side;

    double area() {
        return side * side;
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Shape sh = new Circle();
        sh.radius = sc.nextDouble();
        sh.describe();
        System.out.printf("Area: %.2f%n", sh.area());
    }
}

abstract class Shape {
    double radius;

    void describe() {
        System.out.println("This is a shape");
    }

    abstract double area();
}

class Circle extends Shape {
    double area() {
        return Math.PI * radius * radius;
    }
}

